T = {}
for _line in DATA.strip("\n").split("\n"):
    _raw = _line.split(" | ")
    if len(_raw) != 5:
        raise ValueError("Línea mal formada: " + _line)
    _key = _raw[0]
    # un texto que termina en espacio ("…enviamos al ") mantiene el espacio al traducir
    _tail = " " if _key.endswith(" ") else ""
    T[_key] = tuple((v.strip() + _tail).replace("\\n", "\n") for v in _raw[1:])
